import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import path from 'node:path';
import {executeTrainingCycle,readCycleContinuationJournal} from '../../training-cycle-executor.mjs';
import {createCycleContinuationRegistry} from '../../cycle-continuation-identity.mjs';
const [phase,directory]=process.argv.slice(2),journalPath=path.join(directory,'cycle.json'),remotePath=path.join(directory,'synthetic-remote.json');
const sessions=[{sessionId:'a',executionDigest:'c'.repeat(64)},{sessionId:'b',executionDigest:'d'.repeat(64)}],occurrences=[{occurrenceId:'one',sessionId:'a',date:'2030-01-01'},{occurrenceId:'two',sessionId:'b',date:'2030-01-02'}];
const remote=phase==='first'?{programs:{},reservations:{},creates:0,reserves:0}:JSON.parse(await readFile(remotePath,'utf8'));
const persist=()=>writeFile(remotePath,JSON.stringify(remote));let stopped=false;
const input={journalPath,accountFingerprint:'a'.repeat(64),prescriptionDigest:'b'.repeat(64),sessions,occurrences,
 revalidate:async()=>{if(phase==='first'){const journal=await readCycleContinuationJournal(journalPath);if(journal.sessions.a.state==='verified'){stopped=true;throw Error('fresh-science-ended-after-first-verified');}}},checkCalendar:async()=>{},
 createSession:async(session,baseline,markDispatch)=>{await baseline(Object.values(remote.programs));await markDispatch();assert.equal(remote.programs[session.sessionId],undefined);const code=`literal-${session.sessionId}`;remote.programs[session.sessionId]=code;remote.creates++;await persist();return code;},
 reconcileSession:async session=>remote.programs[session.sessionId]??null,verifySession:async(session,code)=>remote.programs[session.sessionId]===code,
 reserve:async(row,code,markDispatch)=>{await markDispatch();assert.equal(remote.reservations[row.date],undefined);remote.reservations[row.date]=code;remote.reserves++;await persist();},verifyReservation:async(row,code)=>remote.reservations[row.date]===code};
if(phase==='first'){await assert.rejects(executeTrainingCycle(input),/fresh-science-ended-after-first-verified/);assert.equal(stopped,true);const journal=await readCycleContinuationJournal(journalPath);assert.equal(journal.sessions.a.state,'verified');assert.equal(journal.sessions.b.state,'new');assert.equal(remote.creates,1);assert.equal(remote.reserves,0);await writeFile(path.join(directory,'original-identity.txt'),journal.identity);console.log(JSON.stringify({phase,verifiedCode:journal.sessions.a.templateCode,creates:remote.creates,terminalExpected:true}));}
else if(phase==='renewed'){const journal=await readCycleContinuationJournal(journalPath),registry=createCycleContinuationRegistry(),minted=registry.mint({profile:'synthetic',accountFingerprint:input.accountFingerprint,prescriptionDigest:input.prescriptionDigest,sessions,occurrences,journalPath,journalRoot:directory,journal});assert.equal(minted.scientificApproval,false);assert.equal(minted.mutationAuthorized,false);const bound=registry.bindRenewedExecution(minted.handle,{profile:'synthetic',accountFingerprint:input.accountFingerprint,sessions,occurrences,explicitResumeIntent:'resume-original-exact-cycle'});const result=await executeTrainingCycle({...input,...bound,continuationCheckpointFloor:journal});assert.equal(result.complete,true);assert.equal(remote.creates,2);assert.equal(remote.reserves,2);assert.equal(result.programs.a.templateCode,'literal-a');assert.equal((await readCycleContinuationJournal(journalPath)).identity,await readFile(path.join(directory,'original-identity.txt'),'utf8'));console.log(JSON.stringify({phase,creates:remote.creates,reserves:remote.reserves,verifiedCode:result.programs.a.templateCode,terminalExpected:true}));}
else throw Error('Unknown synthetic process phase');
